      "longQuestions": [
        {
                "id": "cls2-ur-ch01-lq1",
                "question": "\u0633\u0628\u0642 \"\u062d\u0645\u062f (\u0646\u0638\u0645)\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0627\u067e\u0646\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0645\u06cc\u06ba \u062a\u062d\u0631\u06cc\u0631 \u06a9\u0631\u06cc\u06ba\u06d4",
                "answer": "\u0627\u0633 \u062d\u0645\u062f \u0645\u06cc\u06ba \u0634\u0627\u0639\u0631 \u0627\u0644\u0644\u06c1 \u062a\u0639\u0627\u0644\u06cc\u0670 \u06a9\u06cc \u0631\u062d\u0645\u062a\u060c \u0628\u0631\u06a9\u062a \u0627\u0648\u0631 \u0639\u0638\u0645\u062a \u06a9\u0627 \u0627\u0639\u062a\u0631\u0627\u0641 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4 \u06a9\u0627\u0626\u0646\u0627\u062a \u06a9\u06cc \u06c1\u0631 \u0634\u06d2\u060c \u0633\u0648\u0631\u062c\u060c \u0686\u0627\u0646\u062f\u060c \u067e\u06be\u0648\u0644 \u0627\u0648\u0631 \u062a\u0627\u0631\u06d2 \u0627\u0644\u0644\u06c1 \u06a9\u06cc \u0642\u062f\u0631\u062a \u06a9\u06cc \u06af\u0648\u0627\u06c1\u06cc \u062f\u06cc\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0634\u0627\u0639\u0631 \u0627\u0644\u0644\u06c1 \u062a\u0639\u0627\u0644\u06cc\u0670 \u0633\u06d2 \u062f\u0639\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06c1\u0645\u06cc\u06ba \u0646\u06cc\u06a9\u06cc \u0627\u0648\u0631 \u0635\u0631\u0627\u0637\u0650 \u0645\u0633\u062a\u0642\u06cc\u0645 \u067e\u0631 \u0686\u0644\u0646\u06d2 \u06a9\u06cc \u062a\u0648\u0641\u06cc\u0642 \u0639\u0637\u0627 \u0641\u0631\u0645\u0627\u060c \u06c1\u0645\u062a\u060c \u0639\u0632\u062a \u0627\u0648\u0631 \u0639\u0644\u0645 \u06a9\u06cc \u062f\u0648\u0644\u062a \u0633\u06d2 \u0646\u0648\u0627\u0632\u06d4",
                "urdu": "\u0633\u0628\u0642 \"\u062d\u0645\u062f (\u0646\u0638\u0645)\" \u06a9\u06d2 \u0627\u06c1\u0645 \u0646\u06a9\u0627\u062a \u0627\u0648\u0631 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0627\u0633 \u062d\u0645\u062f \u0645\u06cc\u06ba \u0634\u0627\u0639\u0631 \u0627\u0644\u0644\u06c1 \u062a\u0639\u0627\u0644\u06cc\u0670 \u06a9\u06cc \u0631\u062d\u0645\u062a\u060c \u0628\u0631\u06a9\u062a \u0627\u0648\u0631 \u0639\u0638\u0645\u062a \u06a9\u0627 \u0627\u0639\u062a\u0631\u0627\u0641 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4 \u06a9\u0627\u0626\u0646\u0627\u062a \u06a9\u06cc \u06c1\u0631 \u0634\u06d2\u060c \u0633\u0648\u0631\u062c\u060c \u0686\u0627\u0646\u062f\u060c \u067e\u06be\u0648\u0644 \u0627\u0648\u0631 \u062a\u0627\u0631\u06d2 \u0627\u0644\u0644\u06c1 \u06a9\u06cc \u0642\u062f\u0631\u062a \u06a9\u06cc \u06af\u0648\u0627\u06c1\u06cc \u062f\u06cc\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0634\u0627\u0639\u0631 \u0627\u0644\u0644\u06c1 \u062a\u0639\u0627\u0644\u06cc\u0670 \u0633\u06d2 \u062f\u0639\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06c1\u0645\u06cc\u06ba \u0646\u06cc\u06a9\u06cc \u0627\u0648\u0631 \u0635\u0631\u0627\u0637\u0650 \u0645\u0633\u062a\u0642\u06cc\u0645 \u067e\u0631 \u0686\u0644\u0646\u06d2 \u06a9\u06cc \u062a\u0648\u0641\u06cc\u0642 \u0639\u0637\u0627 \u0641\u0631\u0645\u0627\u060c \u06c1\u0645\u062a\u060c \u0639\u0632\u062a \u0627\u0648\u0631 \u0639\u0644\u0645 \u06a9\u06cc \u062f\u0648\u0644\u062a \u0633\u06d2 \u0646\u0648\u0627\u0632\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0645\u0647\u0645 \u067c\u06a9\u064a \u0628\u06cc\u0627\u0646 \u06a9\u0693\u0626.",
                "pashtoAns": "\u067e\u0647 \u062f\u06d0 \u062d\u0645\u062f \u06a9\u06d0 \u062f \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u06cc \u062f \u0631\u062d\u0645\u062a \u0627\u0648 \u0639\u0638\u0645\u062a \u0633\u062a\u0627\u06cc\u0646\u0647 \u0634\u0648\u06d0 \u062f\u0647. \u0644\u0645\u0631\u060c \u0633\u067e\u0648\u0696\u0645\u06cd \u0627\u0648 \u067c\u0648\u0644 \u06a9\u0627\u0626\u0646\u0627\u062a \u062f \u0647\u063a\u0647 \u062f \u0642\u062f\u0631\u062a \u0646\u069a\u06d0 \u062f\u064a. \u0634\u0627\u0639\u0631 \u0644\u0647 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u06cc \u0685\u062e\u0647 \u062f \u0646\u06d0\u06a9\u06cd\u060c \u067e\u0648\u0647\u06d0 \u0627\u0648 \u0639\u0632\u062a \u063a\u0648\u069a\u062a\u0646\u0647 \u06a9\u0648\u064a."
        }
],
