                "question": "\u0622\u067e\u0610 \u06a9\u06d2 \u0648\u0627\u0644\u062f \u0627\u0648\u0631 \u0648\u0627\u0644\u062f\u06c1 \u06a9\u0627 \u0646\u0627\u0645 \u06a9\u06cc\u0627 \u062a\u06be\u0627\u061f",
                "answer": "\u0622\u067e\u0610 \u06a9\u06d2 \u0648\u0627\u0644\u062f \u06a9\u0627 \u0646\u0627\u0645 \u062d\u0636\u0631\u062a \u0639\u0628\u062f\u0627\u0644\u0644\u06c1 \u0627\u0648\u0631 \u0648\u0627\u0644\u062f\u06c1 \u06a9\u0627 \u0646\u0627\u0645 \u062d\u0636\u0631\u062a \u0628\u06cc \u0628\u06cc \u0622\u0645\u0646\u06c1 \u062a\u06be\u0627\u06d4",
