      "longQuestions": [
        {
                "id": "cls2-ur-ch03-lq1",
                "question": "\u0633\u0628\u0642 \"\u067e\u06cc\u0627\u0631\u06d2 \u0631\u0633\u0648\u0644 \u062e\u0627\u062a\u0645 \u0627\u0644\u0646\u0628\u06cc\u06cc\u0646 \ufdfa\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0627\u067e\u0646\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0645\u06cc\u06ba \u062a\u062d\u0631\u06cc\u0631 \u06a9\u0631\u06cc\u06ba\u06d4",
                "answer": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u062d\u0636\u0648\u0631 \u0627\u06a9\u0631\u0645 \u0635\u0644\u06cc \u0627\u0644\u0644\u06c1 \u0639\u0644\u06cc\u06c1 \u0648\u0633\u0644\u0645 \u06a9\u06cc \u0648\u0644\u0627\u062f\u062a\u0650 \u0628\u0627 \u0633\u0639\u0627\u062f\u062a\u060c \u0633\u0686\u0627\u0626\u06cc\u060c \u062f\u06cc\u0627\u0646\u062a \u062f\u0627\u0631\u06cc \u0627\u0648\u0631 \u0646\u0628\u0648\u062a \u06a9\u06d2 \u0648\u0627\u0642\u0639\u0627\u062a \u0628\u06cc\u0627\u0646 \u06c1\u0648\u0626\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0622\u067e\u0610 \u06a9\u0648 \u0628\u0686\u067e\u0646 \u0633\u06d2 \u0635\u0627\u062f\u0642 \u0627\u0648\u0631 \u0627\u0645\u06cc\u0646 \u0645\u0627\u0646\u0627 \u062c\u0627\u062a\u0627 \u062a\u06be\u0627\u06d4 \u0622\u067e\u0610 \u0646\u06d2 \u0627\u0646\u0633\u0627\u0646\u06cc\u062a \u06a9\u0648 \u062d\u0633\u0646\u0650 \u0627\u062e\u0644\u0627\u0642\u060c \u0639\u062f\u0644 \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u0627\u0644\u0644\u06c1 \u06a9\u06cc \u0628\u0646\u062f\u06af\u06cc \u06a9\u0627 \u062f\u0631\u0633 \u062f\u06cc\u0627\u06d4",
                "urdu": "\u0633\u0628\u0642 \"\u067e\u06cc\u0627\u0631\u06d2 \u0631\u0633\u0648\u0644 \u062e\u0627\u062a\u0645 \u0627\u0644\u0646\u0628\u06cc\u06cc\u0646 \ufdfa\" \u06a9\u06d2 \u0627\u06c1\u0645 \u0646\u06a9\u0627\u062a \u0627\u0648\u0631 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u062d\u0636\u0648\u0631 \u0627\u06a9\u0631\u0645 \u0635\u0644\u06cc \u0627\u0644\u0644\u06c1 \u0639\u0644\u06cc\u06c1 \u0648\u0633\u0644\u0645 \u06a9\u06cc \u0648\u0644\u0627\u062f\u062a\u0650 \u0628\u0627 \u0633\u0639\u0627\u062f\u062a\u060c \u0633\u0686\u0627\u0626\u06cc\u060c \u062f\u06cc\u0627\u0646\u062a \u062f\u0627\u0631\u06cc \u0627\u0648\u0631 \u0646\u0628\u0648\u062a \u06a9\u06d2 \u0648\u0627\u0642\u0639\u0627\u062a \u0628\u06cc\u0627\u0646 \u06c1\u0648\u0626\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0622\u067e\u0610 \u06a9\u0648 \u0628\u0686\u067e\u0646 \u0633\u06d2 \u0635\u0627\u062f\u0642 \u0627\u0648\u0631 \u0627\u0645\u06cc\u0646 \u0645\u0627\u0646\u0627 \u062c\u0627\u062a\u0627 \u062a\u06be\u0627\u06d4 \u0622\u067e\u0610 \u0646\u06d2 \u0627\u0646\u0633\u0627\u0646\u06cc\u062a \u06a9\u0648 \u062d\u0633\u0646\u0650 \u0627\u062e\u0644\u0627\u0642\u060c \u0639\u062f\u0644 \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u0627\u0644\u0644\u06c1 \u06a9\u06cc \u0628\u0646\u062f\u06af\u06cc \u06a9\u0627 \u062f\u0631\u0633 \u062f\u06cc\u0627\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0645\u0647\u0645 \u067c\u06a9\u064a \u0628\u06cc\u0627\u0646 \u06a9\u0693\u0626.",
                "pashtoAns": "\u067e\u0647 \u062f\u06d0 \u062f\u0631\u0633 \u06a9\u06d0 \u062f \u062d\u0636\u0631\u062a \u0645\u062d\u0645\u062f \u0635\u0644\u06cc \u0627\u0644\u0644\u0647 \u0639\u0644\u06cc\u0647 \u0648\u0633\u0644\u0645 \u0646\u06d0\u06a9 \u0627\u062e\u0644\u0627\u0642\u060c \u0632\u06d0\u0696\u06d0\u062f\u0646\u0647 \u0627\u0648 \u062f \u0647\u063a\u0647 \u062f \u0635\u062f\u0627\u0642\u062a \u0627\u0648 \u0627\u0645\u0627\u0646\u062a \u0635\u0641\u062a\u0648\u0646\u0647 \u0628\u06cc\u0627\u0646 \u0634\u0648\u064a \u062f\u064a."
        }
],
