                "id": "cls2-ur-ch04-lq1",
                "question": "\u0633\u0628\u0642 \"\u0628\u0627\u0646\u0648 \u06a9\u0627 \u0637\u0648\u0637\u0627\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0627\u067e\u0646\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0645\u06cc\u06ba \u062a\u062d\u0631\u06cc\u0631 \u06a9\u0631\u06cc\u06ba\u06d4",
                "answer": "\u0628\u0627\u0646\u0648 \u0646\u06d2 \u0627\u06cc\u06a9 \u0637\u0648\u0637\u0627 \u067e\u0627\u0644\u0627 \u06c1\u0648\u0627 \u062a\u06be\u0627\u06d4 \u062c\u0628 \u0627\u0633 \u0646\u06d2 \u062f\u06cc\u06a9\u06be\u0627 \u06a9\u06c1 \u0637\u0648\u0637\u0627 \u0642\u06cc\u062f \u0633\u06d2 \u0627\u062f\u0627\u0633 \u06c1\u06d2 \u0627\u0648\u0631 \u06a9\u06be\u0644\u06d2 \u0622\u0633\u0645\u0627\u0646 \u0645\u06cc\u06ba \u0627\u0691\u0646\u0627 \u0686\u0627\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u062a\u0648 \u0627\u0633 \u0646\u06d2 \u0631\u062d\u0645 \u062f\u0644\u06cc \u06a9\u0627 \u0645\u0638\u0627\u06c1\u0631\u06c1 \u06a9\u0631\u062a\u06d2 \u06c1\u0648\u0626\u06d2 \u0627\u0633\u06d2 \u0622\u0632\u0627\u062f \u06a9\u0631 \u062f\u06cc\u0627\u06d4 \u067e\u0631\u0646\u062f\u0648\u06ba \u06a9\u0648 \u0642\u06cc\u062f \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u0622\u0632\u0627\u062f \u0641\u0636\u0627 \u0645\u06cc\u06ba \u0631\u06c1\u0646\u06d2 \u062f\u06cc\u0646\u0627 \u0686\u0627\u06c1\u06cc\u06d2\u06d4",
                "urdu": "\u0633\u0628\u0642 \"\u0628\u0627\u0646\u0648 \u06a9\u0627 \u0637\u0648\u0637\u0627\" \u06a9\u06d2 \u0627\u06c1\u0645 \u0646\u06a9\u0627\u062a \u0627\u0648\u0631 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0628\u0627\u0646\u0648 \u0646\u06d2 \u0627\u06cc\u06a9 \u0637\u0648\u0637\u0627 \u067e\u0627\u0644\u0627 \u06c1\u0648\u0627 \u062a\u06be\u0627\u06d4 \u062c\u0628 \u0627\u0633 \u0646\u06d2 \u062f\u06cc\u06a9\u06be\u0627 \u06a9\u06c1 \u0637\u0648\u0637\u0627 \u0642\u06cc\u062f \u0633\u06d2 \u0627\u062f\u0627\u0633 \u06c1\u06d2 \u0627\u0648\u0631 \u06a9\u06be\u0644\u06d2 \u0622\u0633\u0645\u0627\u0646 \u0645\u06cc\u06ba \u0627\u0691\u0646\u0627 \u0686\u0627\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u062a\u0648 \u0627\u0633 \u0646\u06d2 \u0631\u062d\u0645 \u062f\u0644\u06cc \u06a9\u0627 \u0645\u0638\u0627\u06c1\u0631\u06c1 \u06a9\u0631\u062a\u06d2 \u06c1\u0648\u0626\u06d2 \u0627\u0633\u06d2 \u0622\u0632\u0627\u062f \u06a9\u0631 \u062f\u06cc\u0627\u06d4 \u067e\u0631\u0646\u062f\u0648\u06ba \u06a9\u0648 \u0642\u06cc\u062f \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u0622\u0632\u0627\u062f \u0641\u0636\u0627 \u0645\u06cc\u06ba \u0631\u06c1\u0646\u06d2 \u062f\u06cc\u0646\u0627 \u0686\u0627\u06c1\u06cc\u06d2\u06d4",
