      "longQuestions": [
        {
                "id": "cls2-ur-ch08-lq1",
                "question": "\u0633\u0628\u0642 \"\u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u0631\u062d\u0645\u06c3 \u0627\u0644\u0644\u06c1 \u0639\u0644\u06cc\u06c1\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0627\u067e\u0646\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0645\u06cc\u06ba \u062a\u062d\u0631\u06cc\u0631 \u06a9\u0631\u06cc\u06ba\u06d4",
                "answer": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u0628\u0627\u0628\u0627\u0626\u06d2 \u0642\u0648\u0645 \u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u0645\u062d\u0645\u062f \u0639\u0644\u06cc \u062c\u0646\u0627\u062d \u06a9\u06cc \u0648\u0644\u0627\u062f\u062a\u060c \u062a\u0639\u0644\u06cc\u0645\u060c \u0633\u06cc\u0627\u0633\u062a\u060c \u0627\u0648\u0631 \u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u06a9\u06d2 \u0642\u06cc\u0627\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0639\u0638\u06cc\u0645 \u0627\u0644\u0634\u0627\u0646 \u062e\u062f\u0645\u0627\u062a \u06a9\u0627 \u0630\u06a9\u0631 \u06c1\u06d2\u06d4 \u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u06a9\u06d2 \u0633\u0646\u06c1\u0631\u06cc \u0627\u0635\u0648\u0644 \u0627\u062a\u062d\u0627\u062f\u060c \u0627\u06cc\u0645\u0627\u0646 \u0627\u0648\u0631 \u062a\u0646\u0638\u06cc\u0645 \u06c1\u0645\u06cc\u06ba \u06a9\u0627\u0645\u06cc\u0627\u0628\u06cc \u06a9\u0627 \u0631\u0627\u0633\u062a\u06c1 \u062f\u06a9\u06be\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4",
                "urdu": "\u0633\u0628\u0642 \"\u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u0631\u062d\u0645\u06c3 \u0627\u0644\u0644\u06c1 \u0639\u0644\u06cc\u06c1\" \u06a9\u06d2 \u0627\u06c1\u0645 \u0646\u06a9\u0627\u062a \u0627\u0648\u0631 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u0628\u0627\u0628\u0627\u0626\u06d2 \u0642\u0648\u0645 \u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u0645\u062d\u0645\u062f \u0639\u0644\u06cc \u062c\u0646\u0627\u062d \u06a9\u06cc \u0648\u0644\u0627\u062f\u062a\u060c \u062a\u0639\u0644\u06cc\u0645\u060c \u0633\u06cc\u0627\u0633\u062a\u060c \u0627\u0648\u0631 \u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u06a9\u06d2 \u0642\u06cc\u0627\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0639\u0638\u06cc\u0645 \u0627\u0644\u0634\u0627\u0646 \u062e\u062f\u0645\u0627\u062a \u06a9\u0627 \u0630\u06a9\u0631 \u06c1\u06d2\u06d4 \u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u06a9\u06d2 \u0633\u0646\u06c1\u0631\u06cc \u0627\u0635\u0648\u0644 \u0627\u062a\u062d\u0627\u062f\u060c \u0627\u06cc\u0645\u0627\u0646 \u0627\u0648\u0631 \u062a\u0646\u0638\u06cc\u0645 \u06c1\u0645\u06cc\u06ba \u06a9\u0627\u0645\u06cc\u0627\u0628\u06cc \u06a9\u0627 \u0631\u0627\u0633\u062a\u06c1 \u062f\u06a9\u06be\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0645\u0647\u0645 \u067c\u06a9\u064a \u0628\u06cc\u0627\u0646 \u06a9\u0693\u0626.",
                "pashtoAns": "\u067e\u0647 \u062f\u06d0 \u062f\u0631\u0633 \u06a9\u06d0 \u062f \u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u062f \u0628\u0646\u0633\u067c \u0627\u06cc\u069a\u0648\u062f\u0648\u0646\u06a9\u064a \u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u0645\u062d\u0645\u062f \u0639\u0644\u064a \u062c\u0646\u0627\u062d \u0698\u0648\u0646\u062f\u060c \u0647\u0685\u06d0 \u0627\u0648 \u0646\u06d0\u06a9 \u0627\u0635\u0648\u0644 \u0628\u06cc\u0627\u0646 \u0634\u0648\u064a \u062f\u064a."
        }
],
      "grammar": "اسم، فعل، صفت، واحد جمع، الفاظ متضاد اور جملہ سازی۔"
