                "q": "\u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u0631\u062d\u0645\u06c3 \u0627\u0644\u0644\u06c1 \u0639\u0644\u06cc\u06c1 \u06a9\u0628 \u0627\u0648\u0631 \u06a9\u06c1\u0627\u06ba \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0626\u06d2\u061f",
                "ans": "\u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u06f2\u06f5 \u062f\u0633\u0645\u0628\u0631 \u06f1\u06f8\u06f7\u06f6\u0621 \u06a9\u0648 \u06a9\u0631\u0627\u0686\u06cc \u0645\u06cc\u06ba \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0626\u06d2\u06d4",
                "urdu": "\u0642\u0627\u0626\u062f \u0627\u0639\u0638\u0645 \u06a9\u0628 \u0627\u0648\u0631 \u06a9\u06c1\u0627\u06ba \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0626\u06d2\u061f"
