                "question": "\u062d\u062f\u06cc\u062b \u0645\u0628\u0627\u0631\u06a9\u06c1 \u0645\u06cc\u06ba \u0645\u062d\u0646\u062a \u06a9\u0634 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u0641\u0631\u0645\u0627\u06cc\u0627 \u06af\u06cc\u0627\u061f",
