                "answer": "\u06c1\u0645\u06cc\u06ba \u0627\u0646 \u06a9\u06cc \u0639\u0632\u062a \u06a9\u0631\u0646\u06cc \u0686\u0627\u06c1\u06cc\u06d2 \u0627\u0648\u0631 \u0627\u0646 \u06a9\u0627 \u0634\u06a9\u0631\u06cc\u06c1 \u0627\u062f\u0627 \u06a9\u0631\u0646\u0627 \u0686\u0627\u06c1\u06cc\u06d2\u06d4",
                "urdu": "\u06a9\u06cc\u0633\u0627 \u0628\u0631\u062a\u0627\u0624 \u06a9\u0631\u06cc\u06ba\u061f",
                "pashto": "\u0644\u0647 \u0645\u0632\u062f\u0648\u0631\u0627\u0646\u0648 \u0633\u0631\u0647 \u0628\u0627\u06cc\u062f \u0685\u0647 \u0689\u0648\u0644 \u0686\u0644\u0646\u062f \u0648\u0634\u064a\u061f",
