      "longQuestions": [
        {
                "id": "cls2-ur-ch11-lq1",
                "question": "\u0633\u0628\u0642 \"\u0645\u062d\u0646\u062a \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u06d2\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0627\u067e\u0646\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0645\u06cc\u06ba \u062a\u062d\u0631\u06cc\u0631 \u06a9\u0631\u06cc\u06ba\u06d4",
                "answer": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u06a9\u0633\u0627\u0646\u060c \u0627\u0633\u062a\u0627\u062f\u060c \u0688\u0627\u06a9\u0679\u0631\u060c \u0628\u0691\u06be\u0626\u06cc \u0627\u0648\u0631 \u0635\u0641\u0627\u0626\u06cc \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u06a9\u06cc \u0645\u062d\u0646\u062a \u06a9\u06cc \u0627\u06c1\u0645\u06cc\u062a \u0628\u06cc\u0627\u0646 \u06a9\u06cc \u06af\u0626\u06cc \u06c1\u06d2\u06d4 \u0645\u062d\u0646\u062a \u0645\u06cc\u06ba \u0639\u0638\u0645\u062a \u06c1\u06d2 \u0627\u0648\u0631 \u06c1\u0631 \u067e\u06cc\u0634\u06c1 \u0642\u0627\u0628\u0644\u0650 \u0627\u062d\u062a\u0631\u0627\u0645 \u06c1\u06d2\u06d4 \u0627\u0633\u0644\u0627\u0645 \u0645\u062d\u0646\u062a \u06a9\u0634 \u06a9\u0648 \u0627\u0644\u0644\u06c1 \u06a9\u0627 \u062f\u0648\u0633\u062a \u0642\u0631\u0627\u0631 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4",
                "urdu": "\u0633\u0628\u0642 \"\u0645\u062d\u0646\u062a \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u06d2\" \u06a9\u06d2 \u0627\u06c1\u0645 \u0646\u06a9\u0627\u062a \u0627\u0648\u0631 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u06a9\u0633\u0627\u0646\u060c \u0627\u0633\u062a\u0627\u062f\u060c \u0688\u0627\u06a9\u0679\u0631\u060c \u0628\u0691\u06be\u0626\u06cc \u0627\u0648\u0631 \u0635\u0641\u0627\u0626\u06cc \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u06a9\u06cc \u0645\u062d\u0646\u062a \u06a9\u06cc \u0627\u06c1\u0645\u06cc\u062a \u0628\u06cc\u0627\u0646 \u06a9\u06cc \u06af\u0626\u06cc \u06c1\u06d2\u06d4 \u0645\u062d\u0646\u062a \u0645\u06cc\u06ba \u0639\u0638\u0645\u062a \u06c1\u06d2 \u0627\u0648\u0631 \u06c1\u0631 \u067e\u06cc\u0634\u06c1 \u0642\u0627\u0628\u0644\u0650 \u0627\u062d\u062a\u0631\u0627\u0645 \u06c1\u06d2\u06d4 \u0627\u0633\u0644\u0627\u0645 \u0645\u062d\u0646\u062a \u06a9\u0634 \u06a9\u0648 \u0627\u0644\u0644\u06c1 \u06a9\u0627 \u062f\u0648\u0633\u062a \u0642\u0631\u0627\u0631 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0645\u0647\u0645 \u067c\u06a9\u064a \u0628\u06cc\u0627\u0646 \u06a9\u0693\u0626.",
                "pashtoAns": "\u067e\u0647 \u067c\u0648\u0644\u0646\u0647 \u06a9\u06d0 \u0647\u0631 \u06a9\u0627\u0631\u06ab\u0631 \u0627\u0648 \u06a9\u0633\u0628\u06ab\u0631 \u062f \u0627\u062d\u062a\u0631\u0627\u0645 \u0648\u0693 \u062f\u06cc. \u0628\u0632\u06ab\u0631\u060c \u0689\u0627\u06a9\u067c\u0631\u060c \u069a\u0648\u0648\u0646\u06a9\u06cc \u0627\u0648 \u0635\u0641\u0627\u06a9\u0627\u0631 \u067c\u0648\u0644 \u062f \u067c\u0648\u0644\u0646\u06d0 \u062e\u062f\u0645\u062a \u06a9\u0648\u064a. \u062e\u0648\u0627\u0631\u06cc\u06a9\u069a \u062f \u062e\u062f\u0627\u06cc \u062f\u0648\u0633\u062a \u062f\u06cc."
        }
],
