                "q": "\u0627\u0633 \u0633\u0628\u0642 \u0633\u06d2 \u06c1\u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u0627\u062e\u0644\u0627\u0642\u06cc \u0648 \u0639\u0645\u0644\u06cc \u0633\u0628\u0642 \u0645\u0644\u062a\u0627 \u06c1\u06d2\u061f",
                "ans": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u06a9\u0633\u0627\u0646\u060c \u0627\u0633\u062a\u0627\u062f\u060c \u0688\u0627\u06a9\u0679\u0631\u060c \u0628\u0691\u06be\u0626\u06cc \u0627\u0648\u0631 \u0635\u0641\u0627\u0626\u06cc \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u06a9\u06cc \u0645\u062d\u0646\u062a \u06a9\u06cc \u0627\u06c1\u0645\u06cc\u062a \u0628\u06cc\u0627\u0646 \u06a9\u06cc \u06af\u0626\u06cc \u06c1\u06d2\u06d4 \u0645\u062d\u0646\u062a \u0645\u06cc\u06ba \u0639\u0638\u0645\u062a \u06c1\u06d2 \u0627\u0648\u0631 \u06c1\u0631 \u067e\u06cc\u0634\u06c1 \u0642\u0627\u0628\u0644\u0650 \u0627\u062d\u062a\u0631\u0627\u0645 \u06c1\u06d2\u06d4 \u0627\u0633\u0644\u0627\u0645 \u0645\u062d\u0646\u062a \u06a9\u0634 \u06a9\u0648 \u0627\u0644\u0644\u06c1 \u06a9\u0627 \u062f\u0648\u0633\u062a \u0642\u0631\u0627\u0631 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4"
