      "longQuestions": [
        {
                "id": "cls2-ur-ch13-lq1",
                "question": "\u0633\u0628\u0642 \"\u0645\u06cc\u0631\u0627 \u067e\u06cc\u0627\u0631\u0627 \u0648\u0637\u0646 (\u0646\u0638\u0645)\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0627\u067e\u0646\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0645\u06cc\u06ba \u062a\u062d\u0631\u06cc\u0631 \u06a9\u0631\u06cc\u06ba\u06d4",
                "answer": "\u0627\u0633 \u062e\u0648\u0628\u0635\u0648\u0631\u062a \u0642\u0648\u0645\u06cc \u0646\u0638\u0645 \u0645\u06cc\u06ba \u0634\u0627\u0639\u0631 \u0627\u067e\u0646\u06d2 \u0648\u0637\u0646 \u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u0633\u06d2 \u0633\u0686\u06cc \u0645\u062d\u0628\u062a \u06a9\u0627 \u0627\u0638\u06c1\u0627\u0631 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4 \u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u06a9\u06d2 \u067e\u06c1\u0627\u0691\u060c \u062f\u0631\u06cc\u0627\u060c \u0648\u0627\u062f\u06cc\u0627\u06ba \u0627\u0648\u0631 \u0634\u06c1\u0631 \u0633\u0628 \u062f\u0644 \u06a9\u0648 \u0628\u06be\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0628\u0686\u06d2 \u0639\u06c1\u062f \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba \u06a9\u06c1 \u0648\u06c1 \u0639\u0644\u0645 \u062d\u0627\u0635\u0644 \u06a9\u0631 \u06a9\u06d2 \u0627\u067e\u0646\u06d2 \u0648\u0637\u0646 \u06a9\u0627 \u0646\u0627\u0645 \u0631\u0648\u0634\u0646 \u06a9\u0631\u06cc\u06ba \u06af\u06d2\u06d4",
                "urdu": "\u0633\u0628\u0642 \"\u0645\u06cc\u0631\u0627 \u067e\u06cc\u0627\u0631\u0627 \u0648\u0637\u0646 (\u0646\u0638\u0645)\" \u06a9\u06d2 \u0627\u06c1\u0645 \u0646\u06a9\u0627\u062a \u0627\u0648\u0631 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0627\u0633 \u062e\u0648\u0628\u0635\u0648\u0631\u062a \u0642\u0648\u0645\u06cc \u0646\u0638\u0645 \u0645\u06cc\u06ba \u0634\u0627\u0639\u0631 \u0627\u067e\u0646\u06d2 \u0648\u0637\u0646 \u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u0633\u06d2 \u0633\u0686\u06cc \u0645\u062d\u0628\u062a \u06a9\u0627 \u0627\u0638\u06c1\u0627\u0631 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4 \u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u06a9\u06d2 \u067e\u06c1\u0627\u0691\u060c \u062f\u0631\u06cc\u0627\u060c \u0648\u0627\u062f\u06cc\u0627\u06ba \u0627\u0648\u0631 \u0634\u06c1\u0631 \u0633\u0628 \u062f\u0644 \u06a9\u0648 \u0628\u06be\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4 \u0628\u0686\u06d2 \u0639\u06c1\u062f \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba \u06a9\u06c1 \u0648\u06c1 \u0639\u0644\u0645 \u062d\u0627\u0635\u0644 \u06a9\u0631 \u06a9\u06d2 \u0627\u067e\u0646\u06d2 \u0648\u0637\u0646 \u06a9\u0627 \u0646\u0627\u0645 \u0631\u0648\u0634\u0646 \u06a9\u0631\u06cc\u06ba \u06af\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0645\u0647\u0645 \u067c\u06a9\u064a \u0628\u06cc\u0627\u0646 \u06a9\u0693\u0626.",
                "pashtoAns": "\u062f\u0627 \u0645\u0644\u064a \u0646\u0638\u0645 \u0644\u0647 \u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u0633\u0631\u0647 \u062f \u0645\u0627\u0634\u0648\u0645\u0627\u0646\u0648 \u062f \u0645\u06cc\u0646\u06d0\u060c \u062f \u0647\u06d0\u0648\u0627\u062f \u062f \u069a\u06a9\u0644\u0627 \u0627\u0648 \u062f \u0632\u062f\u0647 \u06a9\u0693\u06d0 \u0644\u0647 \u0644\u0627\u0631\u06d0 \u062f \u0647\u06d0\u0648\u0627\u062f \u062f \u067e\u0631\u0645\u062e\u062a\u06ab \u0698\u0645\u0646\u0647 \u0628\u06cc\u0627\u0646\u0648\u064a."
        }
],
