      "longQuestions": [
        {
                "id": "cls2-ur-ch15-lq1",
                "question": "\u0633\u0628\u0642 \"\u0635\u0641\u0627\u0626\u06cc \u06a9\u0627 \u0631\u06a9\u06be\u06cc\u06ba \u062e\u06cc\u0627\u0644\" \u06a9\u0627 \u062e\u0644\u0627\u0635\u06c1 \u0627\u067e\u0646\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0645\u06cc\u06ba \u062a\u062d\u0631\u06cc\u0631 \u06a9\u0631\u06cc\u06ba\u06d4",
                "answer": "\u0635\u0641\u0627\u0626\u06cc \u0646\u0635\u0641 \u0627\u06cc\u0645\u0627\u0646 \u06c1\u06d2\u06d4 \u0637\u0627\u06c1\u0631\u06c1 \u0646\u06d2 \u067e\u0627\u0631\u06a9 \u0645\u06cc\u06ba \u06a9\u0686\u0631\u0627 \u062f\u06cc\u06a9\u06be \u06a9\u0631 \u062e\u0648\u062f \u0635\u0641\u0627\u0626\u06cc \u06a9\u06cc \u0627\u0648\u0631 \u06a9\u0648\u0691\u06d2 \u062f\u0627\u0646 \u06a9\u0627 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0633\u06a9\u06be\u0627\u06cc\u0627\u06d4 \u0635\u0627\u0641 \u0633\u062a\u06be\u0631\u0627 \u0645\u0627\u062d\u0648\u0644 \u0627\u0646\u0633\u0627\u0646 \u06a9\u0648 \u0628\u06cc\u0645\u0627\u0631\u06cc\u0648\u06ba \u0633\u06d2 \u0645\u062d\u0641\u0648\u0638 \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0645\u0639\u0627\u0634\u0631\u06d2 \u06a9\u0648 \u067e\u0631\u06a9\u0634\u0634 \u0628\u0646\u0627\u062a\u0627 \u06c1\u06d2\u06d4",
                "urdu": "\u0633\u0628\u0642 \"\u0635\u0641\u0627\u0626\u06cc \u06a9\u0627 \u0631\u06a9\u06be\u06cc\u06ba \u062e\u06cc\u0627\u0644\" \u06a9\u06d2 \u0627\u06c1\u0645 \u0646\u06a9\u0627\u062a \u0627\u0648\u0631 \u062e\u0644\u0627\u0635\u06c1 \u0644\u06a9\u06be\u06cc\u06ba\u06d4",
                "urduAns": "\u0635\u0641\u0627\u0626\u06cc \u0646\u0635\u0641 \u0627\u06cc\u0645\u0627\u0646 \u06c1\u06d2\u06d4 \u0637\u0627\u06c1\u0631\u06c1 \u0646\u06d2 \u067e\u0627\u0631\u06a9 \u0645\u06cc\u06ba \u06a9\u0686\u0631\u0627 \u062f\u06cc\u06a9\u06be \u06a9\u0631 \u062e\u0648\u062f \u0635\u0641\u0627\u0626\u06cc \u06a9\u06cc \u0627\u0648\u0631 \u06a9\u0648\u0691\u06d2 \u062f\u0627\u0646 \u06a9\u0627 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0633\u06a9\u06be\u0627\u06cc\u0627\u06d4 \u0635\u0627\u0641 \u0633\u062a\u06be\u0631\u0627 \u0645\u0627\u062d\u0648\u0644 \u0627\u0646\u0633\u0627\u0646 \u06a9\u0648 \u0628\u06cc\u0645\u0627\u0631\u06cc\u0648\u06ba \u0633\u06d2 \u0645\u062d\u0641\u0648\u0638 \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0645\u0639\u0627\u0634\u0631\u06d2 \u06a9\u0648 \u067e\u0631\u06a9\u0634\u0634 \u0628\u0646\u0627\u062a\u0627 \u06c1\u06d2\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0645\u0647\u0645 \u067c\u06a9\u064a \u0628\u06cc\u0627\u0646 \u06a9\u0693\u0626.",
                "pashtoAns": "\u067e\u0627\u06a9\u0648\u0627\u0644\u06cc \u0646\u06cc\u0645 \u0627\u06cc\u0645\u0627\u0646 \u062f\u06cc. \u0637\u0627\u0647\u0631\u06d0 \u067e\u0647 \u067e\u0627\u0631\u06a9 \u06a9\u06d0 \u06a9\u062b\u0627\u0641\u0627\u062a \u067e\u0647 \u0689\u0633\u067c \u0628\u06cc\u0646 \u06a9\u06d0 \u0648\u0627\u0686\u0648\u0644. \u0645\u0648\u0646\u0696 \u0628\u0627\u06cc\u062f \u062e\u067e\u0644 \u06a9\u0648\u0631 \u0627\u0648 \u069a\u0648\u0648\u0646\u0681\u06cc \u067e\u0627\u06a9 \u0648\u0633\u0627\u062a\u0648."
        }
],
      "grammar": "اسم، فعل، صفت، واحد جمع، الفاظ متضاد اور جملہ سازی۔"
