                "question": "\u0639\u0644\u0627\u0645\u06c1 \u0627\u0642\u0628\u0627\u0644 \u06a9\u0627 \u0645\u0632\u0627\u0631 \u06a9\u06c1\u0627\u06ba \u0648\u0627\u0642\u0639 \u06c1\u06d2\u061f",
                "answer": "\u0622\u067e \u06a9\u0627 \u0645\u0632\u0627\u0631 \u062a\u0627\u0631\u06cc\u062e\u06cc \u0628\u0627\u062f\u0634\u0627\u06c1\u06cc \u0645\u0633\u062c\u062f \u0644\u0627\u06c1\u0648\u0631 \u06a9\u06d2 \u0627\u062d\u0627\u0637\u06d2 \u06a9\u06d2 \u0628\u0627\u06c1\u0631 \u0648\u0627\u0642\u0639 \u06c1\u06d2\u06d4",
                "urdu": "\u0645\u0632\u0627\u0631 \u06a9\u06c1\u0627\u06ba \u06c1\u06d2\u061f",
                "pashto": "\u062f \u0647\u063a\u0647 \u0632\u06cc\u0627\u0631\u062a \u0686\u06cc\u0631\u062a\u0647 \u062f\u06cc\u061f",
                "pashtoAns": "\u062f \u0647\u063a\u0647 \u0645\u0632\u0627\u0631 \u067e\u0647 \u0644\u0627\u0647\u0648\u0631 \u06a9\u06d0 \u062f \u0628\u0627\u062f\u0634\u0627\u0647\u064a \u062c\u0648\u0645\u0627\u062a \u0645\u062e\u06d0 \u062a\u0647 \u062f\u06cc."
