                "q": "\u0627\u0633 \u0633\u0628\u0642 \u0633\u06d2 \u06c1\u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u0627\u062e\u0644\u0627\u0642\u06cc \u0648 \u0639\u0645\u0644\u06cc \u0633\u0628\u0642 \u0645\u0644\u062a\u0627 \u06c1\u06d2\u061f",
                "ans": "\u0639\u062b\u0645\u0627\u0646 \u0646\u06d2 \u0688\u0631\u0627\u0626\u0646\u06af \u06a9\u06d2 \u0627\u0645\u062a\u062d\u0627\u0646 \u0645\u06cc\u06ba \u0627\u067e\u0646\u06d2 \u062f\u0648\u0633\u062a \u0639\u0645\u0631 \u06a9\u06cc \u0645\u062f\u062f \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u067e\u0646\u06d2 \u0642\u06cc\u0645\u062a\u06cc \u0631\u0646\u06af \u0628\u0627\u0646\u0679\u06d2\u06d4 \u0633\u0686\u06cc \u062f\u0648\u0633\u062a\u06cc \u0627\u06cc\u062b\u0627\u0631\u060c \u06c1\u0645\u062f\u0631\u062f\u06cc \u0627\u0648\u0631 \u0645\u0634\u06a9\u0644 \u0645\u06cc\u06ba \u0633\u0627\u062a\u06be \u0646\u0628\u06be\u0627\u0646\u06d2 \u06a9\u0627 \u0646\u0627\u0645 \u06c1\u06d2\u06d4"
