      "sqs": [
        {
                "q": "\u0631\u06cc\u0644 \u06af\u0627\u0691\u06cc \u06a9\u0646 \u0686\u06cc\u0632\u0648\u06ba \u067e\u0631 \u0686\u0644\u062a\u06cc \u06c1\u06d2\u061f",
                "ans": "\u0631\u06cc\u0644 \u06af\u0627\u0691\u06cc \u0644\u0648\u06c1\u06d2 \u06a9\u06cc \u0645\u0636\u0628\u0648\u0637 \u067e\u0679\u0631\u06cc\u0648\u06ba \u067e\u0631 \u0686\u0644\u062a\u06cc \u06c1\u06d2\u06d4",
                "urdu": "\u0631\u06cc\u0644 \u06af\u0627\u0691\u06cc \u06a9\u0633 \u067e\u0631 \u0686\u0644\u062a\u06cc \u06c1\u06d2\u061f"
        }
],
      "lqs": [
        {
                "q": "\u0627\u0633 \u0633\u0628\u0642 \u0633\u06d2 \u06c1\u0645\u06cc\u06ba \u06a9\u06cc\u0627 \u0627\u062e\u0644\u0627\u0642\u06cc \u0648 \u0639\u0645\u0644\u06cc \u0633\u0628\u0642 \u0645\u0644\u062a\u0627 \u06c1\u06d2\u061f",
                "ans": "\u0627\u0633 \u0633\u0628\u0642 \u0645\u06cc\u06ba \u0631\u06cc\u0644 \u06af\u0627\u0691\u06cc \u06a9\u06d2 \u062f\u0644\u06a9\u0634 \u0633\u0641\u0631 \u0627\u0648\u0631 \u0631\u06cc\u0644\u0648\u06d2 \u0646\u0638\u0627\u0645 \u06a9\u06cc \u0627\u0641\u0627\u062f\u06cc\u062a \u06a9\u0627 \u0630\u06a9\u0631 \u06c1\u06d2\u06d4 \u0631\u06cc\u0644 \u06af\u0627\u0691\u06cc \u067e\u0631 \u0645\u0633\u0627\u0641\u0631 \u0627\u0648\u0631 \u0628\u06be\u0627\u0631\u06cc \u0633\u0627\u0645\u0627\u0646 \u0633\u0633\u062a\u06d2 \u0627\u0648\u0631 \u0645\u062d\u0641\u0648\u0638 \u0637\u0631\u06cc\u0642\u06d2 \u0633\u06d2 \u0627\u06cc\u06a9 \u0634\u06c1\u0631 \u0633\u06d2 \u062f\u0648\u0633\u0631\u06d2 \u0634\u06c1\u0631 \u0645\u0646\u062a\u0642\u0644 \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"
        }
]
