                "q": "\u0645\u06cc\u0644\u06d2 \u0645\u06cc\u06ba \u06a9\u0648\u0646 \u06a9\u0648\u0646 \u0633\u06d2 \u06a9\u06be\u06cc\u0644 \u0627\u0648\u0631 \u06a9\u0631\u062a\u0628 \u06c1\u0648 \u0631\u06c1\u06d2 \u062a\u06be\u06d2\u061f",
                "ans": "\u0645\u06cc\u0644\u06d2 \u0645\u06cc\u06ba \u06af\u06be\u0691 \u062f\u0648\u0691\u060c \u0646\u06cc\u0632\u06c1 \u0628\u0627\u0632\u06cc \u0627\u0648\u0631 \u062c\u06be\u0648\u0644\u06d2 \u0686\u0644 \u0631\u06c1\u06d2 \u062a\u06be\u06d2\u06d4",
