                "urduAns": "\u06cc\u06c1 \u0635\u0648\u0641\u06cc \u062a\u0628\u0633\u0645 \u06a9\u06cc \u0627\u06cc\u06a9 \u0645\u0632\u0627\u062d\u06cc\u06c1 \u0627\u0648\u0631 \u062f\u0644\u06a9\u0634 \u0646\u0638\u0645 \u06c1\u06d2 \u062c\u0633 \u0645\u06cc\u06ba \u062e\u06cc\u0627\u0644\u06cc \u06a9\u0631\u062f\u0627\u0631 \u0679\u0648\u0679 \u0628\u0679\u0648\u0679 \u06a9\u06cc \u0639\u062c\u06cc\u0628 \u0648 \u063a\u0631\u06cc\u0628 \u062a\u06cc\u0646 \u067e\u06c1\u06cc\u0648\u06ba \u0648\u0627\u0644\u06cc \u0645\u0648\u0679\u0631 \u06a9\u0627\u0631 \u06a9\u0627 \u0630\u06a9\u0631 \u06c1\u06d2\u06d4 \u0646\u0638\u0645 \u067e\u0691\u06be \u06a9\u0631 \u0628\u0686\u06d2 \u06c1\u0646\u0633\u062a\u06d2 \u0627\u0648\u0631 \u0645\u062d\u0638\u0648\u0638 \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4",
                "pashto": "\u062f \u062f\u06d0 \u0644\u0648\u0633\u062a \u0645\u0647\u0645 \u067c\u06a9\u064a \u0628\u06cc\u0627\u0646 \u06a9\u0693\u0626.",
                "pashtoAns": "\u062f\u0627 \u062f \u0635\u0648\u0641\u064a \u062a\u0628\u0633\u0645 \u06cc\u0648 \u062e\u0646\u062f\u0648\u0646\u06a9\u06cc \u0627\u0648 \u067e\u0647 \u0632\u0693\u0647 \u067e\u0648\u0631\u06d0 \u0646\u0638\u0645 \u062f\u06cc \u0686\u06d0 \u0645\u0627\u0634\u0648\u0645\u0627\u0646\u0648 \u062a\u0647 \u062e\u0648\u069a\u064a \u0627\u0648 \u062a\u0641\u0631\u06cc\u062d \u0628\u069a\u064a."
